local GlassMarverMaker = {}
local PRODUCTS = {
    iron_glassmarver = { name = "Železni marmorirna plosca za steklo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni marmorirna plosca za steklo za steklarje." },
    bronze_glassmarver = { name = "Bronast marmorirna plosca za steklo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast marmorirna plosca za steklo za steklarje." },
    silver_glassmarver = { name = "Srebrn marmorirna plosca za steklo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn marmorirna plosca za steklo za steklarje." },
    gilded_glassmarver = { name = "Pozlačen marmorirna plosca za steklo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen marmorirna plosca za steklo za steklarje." },
    jewel_set_glassmarver = { name = "Draguljast marmorirna plosca za steklo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast marmorirna plosca za steklo za steklarje." },
    royal_sovereign_glassmarver = { name = "Kraljevski suveren marmorirna plosca za steklo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren marmorirna plosca za steklo z biseri za krono." },
}
local BUILDINGS = {
    glassmarver_workshop = { name = "Glassmarver delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    glassmarver_house = { name = "Glassmarver hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_glassmarver_atelier = { name = "Mojstrski glassmarver atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glassmarver_palace = { name = "Suverena glassmarver palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassMarverMaker.ironStock = 12; GlassMarverMaker.bronzeStock = 10; GlassMarverMaker.woodStock = 18; GlassMarverMaker.leatherStock = 10; GlassMarverMaker.silverStock = 8; GlassMarverMaker.goldStock = 6; GlassMarverMaker.jewelStock = 4; GlassMarverMaker.pearlStock = 4
GlassMarverMaker.productStock = {}; GlassMarverMaker.buildings = {}; GlassMarverMaker.maker = nil; GlassMarverMaker.activeMaking = {}; GlassMarverMaker.totalProducts = 0; GlassMarverMaker.dayTimer = 0
function GlassMarverMaker.init() GlassMarverMaker.ironStock=12; GlassMarverMaker.bronzeStock=10; GlassMarverMaker.woodStock=18; GlassMarverMaker.leatherStock=10; GlassMarverMaker.silverStock=8; GlassMarverMaker.goldStock=6; GlassMarverMaker.jewelStock=4; GlassMarverMaker.pearlStock=4; GlassMarverMaker.productStock={}; GlassMarverMaker.buildings={}; GlassMarverMaker.maker=nil; GlassMarverMaker.activeMaking={}; GlassMarverMaker.totalProducts=0; GlassMarverMaker.dayTimer=0; print("[GlassMarverMaker] Royal Glass Marver Maker System initialized (6 products, 4 buildings)") end
function GlassMarverMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassMarverMaker.maker={name=n or ("Marmorist "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Marmorist najet: %s (spretnost: %d)",GlassMarverMaker.maker.name,s),"success") end; return true end
function GlassMarverMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassMarverMaker.build(id) local ok,e=GlassMarverMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassMarverMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassMarverMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassMarverMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassMarverMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassMarverMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassMarverMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassMarverMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassMarverMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassMarverMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassMarverMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassMarverMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassMarverMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassMarverMaker.buildings==0 then return false,"Potrebna marmorirna delavnica" end; if not GlassMarverMaker.maker then return false,"Potreben marmorist" end; return true end
function GlassMarverMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassMarverMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassMarverMaker.ironStock=GlassMarverMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassMarverMaker.bronzeStock=GlassMarverMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassMarverMaker.woodStock=GlassMarverMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassMarverMaker.leatherStock=GlassMarverMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassMarverMaker.silverStock=GlassMarverMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassMarverMaker.goldStock=GlassMarverMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassMarverMaker.jewelStock=GlassMarverMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassMarverMaker.pearlStock=GlassMarverMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassMarverMaker.maker then t=math.max(1,t-math.floor(GlassMarverMaker.maker.skill/13)) end; table.insert(GlassMarverMaker.activeMaking,{id="glassmarver_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassMarverMaker.completeMaking(m) local q=1.0+(GlassMarverMaker.getQualityBonus()/100); if GlassMarverMaker.maker then q=q+(GlassMarverMaker.maker.skill/140) end; q=math.min(2.5,q); GlassMarverMaker.productStock[m.productType]=(GlassMarverMaker.productStock[m.productType] or 0)+m.quantity; GlassMarverMaker.totalProducts=GlassMarverMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassMarverMaker.maker then GlassMarverMaker.maker.itemsMade=GlassMarverMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassMarverMaker.maker.skill=math.min(100,GlassMarverMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("PloSca izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassmarver.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassMarverMaker.update(dt) if not _G.state then return end; GlassMarverMaker.dayTimer=GlassMarverMaker.dayTimer+dt; if GlassMarverMaker.dayTimer>=30 then GlassMarverMaker.dayTimer=0; for i=#GlassMarverMaker.activeMaking,1,-1 do local m=GlassMarverMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassMarverMaker.completeMaking(m); table.remove(GlassMarverMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassMarverMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassMarverMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassMarverMaker.getStats() return {ironStock=GlassMarverMaker.ironStock,bronzeStock=GlassMarverMaker.bronzeStock,woodStock=GlassMarverMaker.woodStock,leatherStock=GlassMarverMaker.leatherStock,silverStock=GlassMarverMaker.silverStock,goldStock=GlassMarverMaker.goldStock,jewelStock=GlassMarverMaker.jewelStock,pearlStock=GlassMarverMaker.pearlStock,productStock=GlassMarverMaker.productStock,numBuildings=#GlassMarverMaker.buildings,hasMaker=GlassMarverMaker.maker~=nil,makerName=GlassMarverMaker.maker and GlassMarverMaker.maker.name or "—",makerSkill=GlassMarverMaker.maker and GlassMarverMaker.maker.skill or 0,activeMaking=#GlassMarverMaker.activeMaking,totalProducts=GlassMarverMaker.totalProducts} end
return GlassMarverMaker
